<body>
  <div id="canvas-container">
    <canvas id="canvas" width="800" height="800"></canvas>
  </div>

  <div class="gui-panel" id="gui-panel">
    <h2>Growth</h2>
    <div class="control">
      <label>Neuron Count</label>
      <input type="number" id="neuron-count" min="1" max="10" value="4">
    </div>
    <div class="control">
