      <input type="number" id="curvature" min="0" max="1" step="0.1" value="0.3">
    </div>
    <div class="control">
      <label>Max Branch Length</label>
      <input type="number" id="max-length" min="20" max="200" value="120">
    </div>

    <h2>Synapses</h2>
    <div class="control">
      <label>Distance Threshold</label>
      <input type="number" id="synapse-threshold" min="10" max="100" step="1" value="80">
    </div>
    <div class="control">
      <label>Glow Strength</label>
      <input type="number" id="synapse-glow" min="0" max="10" step="0.1" value="4">
    </div>

    <h2>Pulses</h2>
    <div class="control">
      <label>Pulse Speed</label>
      <input type="number" id="pulse-speed" min="0.1" max="5" step="0.1" value="1">
    </div>
    <div class="control">
      <label>Pulse Frequency</label>
      <input type="number" id="pulse-frequency" min="0.1" max="5" step="0.1" value="0.5">
    </div>
    <div class="control">
      <label>Pulse Brightness</label>
      <input type="number" id="pulse-brightness" min="0" max="1" step="0.1" value="0.8">
    </div>

    <h2>Visuals</h2>
    <div class="control">
      <label>Background Color</label>
      <input type="color" id="bg-color" value="#05070f">
    </div>
    <div class="control">
      <label>Branch Color</label>
      <input type="color" id="branch-color" value="#00e5ff">
