  </div>

  <script type="module">
    import * as dat from 'https://cdn.jsdelivr.net/npm/dat.gui@0.7.9/build/dat.gui.module.js';

    // Canvas setup
    const canvas = document.getElementById('canvas');
    const ctx = canvas.getContext('2d');
    const container = document.getElementById('canvas-container');

    // Resize canvas
    function resizeCanvas() {
      const rect = container.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = rect.height;
    }
    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    // Color palette from requirements
    const colors = {
      background: '#05070f',
      backgroundGlow: '#101a3a',
      mainBranch: '#00e5ff',
      secondaryBranch: '#d6ff00',
      synapse: '#ff2bd6',
      pulse: '#fff36a',
      uiAccent: '#ffd400',
    };

    // GUI setup
    const gui = new dat.GUI({
      container: document.getElementById('gui-panel'),
      width: 320,
      closed: false,
    });

    // Folders
    const growthFolder = gui.addFolder('Growth');
    const synapsesFolder = gui.addFolder('Synapses');
    const pulsesFolder = gui.addFolder('Pulses');
    const visualsFolder = gui.addFolder('Visuals');

    // Initialize controls
    const controls = {
      neuronCount: 4,
      growthSpeed: 1,
      maxDepth: 6,
      splitChance: 30,
      curvature: 0.3,
      maxLength: 120,
      synapseThreshold: 80,
      synapseGlow: 4,
      pulseSpeed: 1,
      pulseFrequency: 0.5,
      pulseBrightness: 0.8,
      bgColor: '#05070f',
      branchColor: '#00e5ff',
      accentColor: '#d6ff00',
      synapseColor: '#ff2bd6',
      pulseColor: '#fff36a',
      isPaused: false,
      isAnimating: true,
    };

    // Add controls to folders
    growthFolder.add(controls, 'neuronCount', 1, 10, 1).name('Neuron Count');
    growthFolder.add(controls, 'growthSpeed', 0.1, 5, 0.1).name('Growth Speed');
    growthFolder.add(controls, 'maxDepth', 1, 15, 1).name('Max Branch Depth');
    growthFolder.add(controls, 'splitChance', 0, 100, 1).name('Split Chance');
    growthFolder.add(controls, 'curvature', 0, 1, 0.1).name('Branch Curvature');
    growthFolder.add(controls, 'maxLength', 20, 200, 10).name('Max Branch Length');

    synapsesFolder.add(controls, 'synapseThreshold', 10, 150, 1).name('Distance Threshold');
    synapsesFolder.add(controls, 'synapseGlow', 0, 10, 0.1).name('Glow Strength');

    pulsesFolder.add(controls, 'pulseSpeed', 0.1, 5, 0.1).name('Pulse Speed');
    pulsesFolder.add(controls, 'pulseFrequency', 0.1, 5, 0.1).name('Pulse Frequency');
    pulsesFolder.add(controls, 'pulseBrightness', 0, 1, 0.1).name('Pulse Brightness');

    visualsFolder.addColor(controls, 'bgColor').name('Background Color').onChange(updateBackground);
    visualsFolder.addColor(controls, 'branchColor').name('Branch Color').onChange(updateBranchColor);
    visualsFolder.addColor(controls, 'accentColor').name('Accent Branch Color').onChange(updateAccentColor);
    visualsFolder.addColor(controls, 'synapseColor').name('Synapse Color').onChange(updateSynapseColor);
    visualsFolder.addColor(controls, 'pulseColor').name('Pulse Color').onChange(updatePulseColor);

    // Add buttons
    const regenerateBtn = gui.add({ action: regenerateNetwork }, 'action').name('Regenerate Network');
    const clearBtn = gui.add({ action: clearCanvas }, 'action').name('Clear Canvas');
    const pauseBtn = gui.add(controls, 'isPaused').name('Pause/Resume');

    // Override button callbacks
    regenerateBtn.__li__.element.querySelector('button').addEventListener('click', () => {
      regenerateNetwork();
    });
    clearBtn.__li__.element.querySelector('button').addEventListener('click', () => {
      clearCanvas();
    });
    pauseBtn.__li__.element.querySelector('button').addEventListener('click', () => {
      controls.isPaused = !controls.isPaused;
      pauseBtn.__li__.element.querySelector('button').textContent = controls.isPaused ? 'Resume' : 'Pause';
    });

    // Force open folders
    growthFolder.open();
    synapsesFolder.open();
    pulsesFolder.open();
    visualsFolder.open();

    // Remove default close button
    gui.__ul__.style.justifyContent = 'flex-start';

    // Network state
    let neurons = [];
    let synapses = [];
    let pulses = [];
    let animationId = null;
    let growthComplete = false;
    let time = 0;

    // Color update functions
    function updateBackground(color) {
      colors.bgColor = color;
      document.body.style.background = color;
    }

    function updateBranchColor(color) {
      colors.mainBranch = color;
    }

    function updateAccentColor(color) {
      colors.secondaryBranch = color;
    }

    function updateSynapseColor(color) {
      colors.synapse = color;
    }

    function updatePulseColor(color) {
      colors.pulse = color;
    }

    // Vector utilities
    function createVector(x, y) {
      return { x, y };
    }

    function addVec(v1, v2) {
      return { x: v1.x + v2.x, y: v1.y + v2.y };
    }

    function subVec(v1, v2) {
      return { x: v1.x - v2.x, y: v1.y - v2.y };
    }

    function scaleVec(v, s) {
      return { x: v.x * s, y: v.y * s };
    }

    function magVec(v) {
      return Math.sqrt(v.x * v.x + v.y * v.y);
    }

    function normalizeVec(v) {
      const m = magVec(v);
      return m > 0 ? { x: v.x / m, y: v.y / m } : { x: 0, y: 0 };
    }

    // Quadratic curve for organic shapes
    function drawQuadraticBranch(ctx, start, cp, end, color, width) {
      ctx.beginPath();
      ctx.moveTo(start.x, start.y);
      ctx.quadraticCurveTo(cp.x, cp.y, end.x, end.y);
      ctx.strokeStyle = color;
      ctx.lineWidth = width;
      ctx.shadowColor = color;
      ctx.shadowBlur = 10;
      ctx.stroke();
      ctx.shadowBlur = 0;
    }

    // Neuron class
    class Neuron {
      constructor(x, y) {
        this.position = createVector(x, y);
        this.branches = [];
        this.tips = [];
        this.active = true;
        this.growthProgress = 0;
      }

      grow(depth, maxDepth, splitChance, curvature, maxLength, growthSpeed) {
        if (depth >= maxDepth || !this.active) return;

        const branchLength = Math.random() * maxLength * 0.6 + maxLength * 0.2;
        const direction = {
          x: (Math.random() - 0.5) * 2,
          y: (Math.random() - 0.5) * 2,
        };

        // Apply curvature
        const curvedDir = {
          x: direction.x + (Math.random() - 0.5) * curvature,
          y: direction.y + (Math.random() - 0.5) * curvature,
        };

        // Calculate new position
        const newPos = {
          x: this.tips[this.tips.length - 1].x + curvedDir.x * branchLength,
          y: this.tips[this.tips.length - 1].y + curvedDir.y * branchLength,
        };

        // Keep within bounds
        const paddedWidth = canvas.width - 40;
        const paddedHeight = canvas.height - 40;
        newPos.x = Math.max(20, Math.min(paddedWidth, newPos.x));
        newPos.y = Math.max(20, Math.min(paddedHeight, newPos.y));

        // Create branch segment
        const startPos = this.tips[this.tips.length - 1] || this.position;
        const thickness = Math.random() * 2 + 1;

        this.branches.push({
          start: createVector(startPos.x, startPos.y),
          end: createVector(newPos.x, newPos.y),
          thickness: thickness,
          depth: depth,
          color: depth % 2 === 0 ? colors.mainBranch : colors.secondaryBranch,
          active: true,
        });

        this.tips.push(createVector(newPos.x, newPos.y));

        // Recursively grow
        if (Math.random() * 100 < splitChance && depth < maxDepth - 1) {
          // Grow straight branch
          this.grow(depth + 1, maxDepth, splitChance, curvature, maxLength, growthSpeed);
        }

        // Grow side branch occasionally
        if (Math.random() * 100 < 20 && depth < maxDepth - 2) {
          const sideBranch = {
            start: createVector(newPos.x, newPos.y),
            end: createVector(newPos.x + (Math.random() - 0.5) * 50, newPos.y + (Math.random() - 0.5) * 50),
            thickness: thickness * 0.6,
            depth: depth,
            color: colors.secondaryBranch,
            active: true,
          };
          this.branches.push(sideBranch);
        }

        this.growthProgress += growthSpeed;
      }

      static generateSeeds(count, canvasWidth, canvasHeight) {
        const seeds = [];
        for (let i = 0; i < count; i++) {
          const x = canvasWidth / 2 + (Math.random() - 0.5) * 100;
          const y = canvasHeight / 2 + (Math.random() - 0.5) * 100;
          seeds.push(new Neuron(x, y));
        }
        return seeds;
      }
    }

    // Synapse detection
    function detectSynapses(neurons, threshold) {
      synapses = [];

      for (let i = 0; i < neurons.length; i++) {
        for (let j = i + 1; j < neurons.length; j++) {
          const tipsI = neurons[i].tips;
          const tipsJ = neurons[j].tips;

          for (let ti = 0; ti < tipsI.length; ti++) {
            for (let tj = 0; tj < tipsJ.length; tj++) {
              const dx = tipsI[ti].x - tipsJ[tj].x;
              const dy = tipsI[ti].y - tipsJ[tj].y;
              const distance = Math.sqrt(dx * dx + dy * dy);

              if (distance < threshold) {
                // Check for duplicate
                const alreadyExists = synapses.some(s => 
                  Math.abs(s.neuron1Index - i) <= 1 && Math.abs(s.neuron2Index - j) <= 1
                );

                if (!alreadyExists) {
                  synapses.push({
                    neuron1Index: i,
                    neuron2Index: j,
                    tip1: createVector(tipsI[ti].x, tipsI[ti].y),
                    tip2: createVector(tipsJ[tj].x, tipsJ[tj].y),
                    glow: 0,
                    pulsePhase: Math.random() * Math.PI * 2,
                  });
                }
              }
            }
          }
        }
      }
    }

    // Pulse class
    class Pulse {
      constructor(start, end, color, speed) {
        this.start = createVector(start.x, start.y);
        this.end = createVector(end.x, end.y);
        this.color = color;
        this.speed = speed;
        this.progress = 0;
        this.completed = false;
      }

      update(dt) {
        if (this.completed) return;
        this.progress += this.speed * dt * 0.016;
        if (this.progress >= 1) {
          this.progress = 0;
          this.completed = true;
        }
      }

      draw() {
        const easedProgress = 1 - Math.pow(1 - this.progress, 3);
        const width = 2 + easedProgress * 3;
        const alpha = 0.5 + easedProgress * 0.5;

        ctx.beginPath();
        ctx.moveTo(this.start.x, this.start.y);
        ctx.lineTo(this.end.x, this.end.y);
        ctx.strokeStyle = this.color;
        ctx.globalAlpha = alpha * alpha;
        ctx.lineWidth = width;
        ctx.shadowColor = this.color;
        ctx.shadowBlur = 15;
        ctx.stroke();
        ctx.shadowBlur = 0;
        ctx.globalAlpha = 1;
      }
    }

    // Animation loop
    function animate(timestamp) {
      time = timestamp / 1000;
      const dt = 16;

      if (!growthComplete || !controls.isPaused) {
        // Update pulses
        for (let i = pulses.length - 1; i >= 0; i--) {
          pulses[i].update(dt);
          if (pulses[i].completed) {
            pulses.splice(i, 1);
          }
        }

        // Generate new pulses periodically
        time += controls.pulseFrequency;
        if (time > 1) {
          time = 0;
          // Create pulses between nearby synapses
          for (const synapse of synapses) {
            if (Math.random() < controls.pulseFrequency * 0.1) {
              pulses.push(new Pulse(
                synapse.tip1,
                synapse.tip2,
                colors.pulse,
                controls.pulseSpeed
              ));
            }
          }
        }

        // Draw background with vignette
        drawBackground();

        // Draw neurons and branches
        for (const neuron of neurons) {
          drawNeuronBranches(neuron);
        }

        // Draw synapses
        for (const synapse of synapses) {
          drawSynapse(synapse);
        }

        // Draw pulses
        for (const pulse of pulses) {
          pulse.draw();
        }
      }

      animationId = requestAnimationFrame(animate);
    }

    function drawBackground() {
      ctx.fillStyle = colors.bgColor;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Vignette
      const gradient = ctx.createRadialGradient(
        canvas.width / 2, canvas.height / 2, 0,
        canvas.width / 2, canvas.height / 2, Math.max(canvas.width, canvas.height) / 2
      );
      gradient.addColorStop(0, 'rgba(5, 7, 15, 0.3)');
      gradient.addStop(1, 'rgba(5, 7, 15, 0.1)');
      ctx.fillStyle = gradient;
      ctx.fill();

      // Subtle noise
      ctx.fillStyle = 'rgba(0, 229, 255, 0.02)';
      for (let i = 0; i < 50; i++) {
        const x = Math.random() * canvas.width;
        const y = Math.random() * canvas.height;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
      }
    }

    function drawNeuronBranches(neuron) {
      for (const branch of neuron.branches) {
        if (!branch.active) continue;

        const thickness = branch.thickness * (1 + controls.synapseGlow * 0.1);

        ctx.beginPath();
        ctx.moveTo(branch.start.x, branch.start.y);
        ctx.quadraticCurveTo(
          (branch.start.x + branch.end.x) / 2 + (Math.random() - 0.5) * 10,
          (branch.start.y + branch.end.y) / 2 + (Math.random() - 0.5) * 10,
          branch.end.x,
          branch.end.y
        );
        ctx.strokeStyle = branch.color;
        ctx.lineWidth = thickness;
        ctx.shadowColor = branch.color;
        ctx.shadowBlur = 8;
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
    }

    function drawSynapse(synapse) {
      const progress = Math.sin(time * controls.pulseSpeed + synapse.pulsePhase) * 0.5 + 0.5;
      const glowStrength = controls.synapseGlow;
      const baseGlow = 10 + glowStrength * 2;

      // Glow effect
      ctx.beginPath();
      ctx.arc(
        (synapse.tip1.x + synapse.tip2.x) / 2,
        (synapse.tip1.y + synapse.tip2.y) / 2,
        5 + progress * 3,
        0,
        Math.PI * 2
      );
      ctx.strokeStyle = synapse.color;
      ctx.lineWidth = 2;
      ctx.shadowColor = synapse.color;
      ctx.shadowBlur = baseGlow * progress;
      ctx.stroke();
      ctx.shadowBlur = 0;

      // Pulse ring
      const pulseAlpha = progress * 0.3;
      ctx.beginPath();
      ctx.arc(
        (synapse.tip1.x + synapse.tip2.x) / 2,
        (synapse.tip1.y + synapse.tip2.y) / 2,
        15 + progress * 10,
        0,
        Math.PI * 2
      );
      ctx.strokeStyle = synapse.color;
      ctx.globalAlpha = pulseAlpha;
      ctx.lineWidth = 1;
      ctx.shadowColor = synapse.color;
      ctx.shadowBlur = 10;
      ctx.stroke();
      ctx.globalAlpha = 1;
      ctx.shadowBlur = 0;
    }

    // Regenerate network
    function regenerateNetwork() {
      neurons = Neuron.generateSeeds(controls.neuronCount, canvas.width, canvas.height);

      // Grow branches step by step
      let depth = 0;
      let maxIterations = controls.maxDepth * 10;

      function growStep() {
        if (depth >= maxIterations || neurons.every(n => n.growthProgress >= controls.maxDepth)) {
          growthComplete = true;
          detectSynapses(neurons, controls.synapseThreshold);
          return;
        }

        for (const neuron of neurons) {
          if (neuron.growthProgress < controls.maxDepth) {
            neuron.grow(
              Math.floor(neuron.growthProgress),
              controls.maxDepth,
              controls.splitChance,
              controls.curvature,
              controls.maxLength,
              controls.growthSpeed
            );
          }
        }

        depth++;
        requestAnimationFrame(growStep);
      }

      growStep();
    }

    // Clear canvas
    function clearCanvas() {
      neurons = [];
      synapses = [];
      pulses = [];
      growthComplete = false;
      time = 0;
      if (animationId) {
        cancelAnimationFrame(animationId);
        animationId = null;
      }
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }

    // Color update functions
    function updateBranchColor(color) {
      colors.mainBranch = color;
    }

    function updateAccentColor(color) {
      colors.secondaryBranch = color;
    }

    function updateSynapseColor(color) {
      colors.synapse = color;
    }

    function updatePulseColor(color) {
      colors.pulse = color;
    }

    // Initial setup
    regenerateNetwork();
    animate();
  </script>
</body>
</html>"}
